using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;

    /// <summary>
    /// Maximum number of sentences in the summary. Defaults to 3.
    /// </summary>
    [Range(1, 20)]
    public int MaxSentences { get; set; } = 3;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
    public int OriginalLength { get; set; }
    public int SummaryLength { get; set; }
}

namespace DocSummary.Services;

public interface IDocumentSummarizer
{
    string Summarize(string text, int maxSentences);
}

public class DocumentSummarizer : IDocumentSummarizer
{
    private static readonly char[] SentenceTerminators = ['.', '!', '?'];

    public string Summarize(string text, int maxSentences)
    {
        if (string.IsNullOrWhiteSpace(text))
            return string.Empty;

        var sentences = SplitIntoSentences(text);

        if (sentences.Count <= maxSentences)
            return string.Join(" ", sentences);

        // Extractive summarization: score each sentence and pick the top ones.
        var scored = sentences
            .Select((s, index) => new { Sentence = s, Score = ScoreSentence(s, index, sentences.Count) })
            .OrderByDescending(x => x.Score)
            .Take(maxSentences)
            .ToList();

        // Return sentences in their original order.
        var selectedSet = new HashSet<string>(scored.Select(x => x.Sentence));
        var ordered = sentences.Where(s => selectedSet.Contains(s)).ToList();

        return string.Join(" ", ordered);
    }

    private static List<string> SplitIntoSentences(string text)
    {
        var sentences = new List<string>();
        int start = 0;

        for (int i = 0; i < text.Length; i++)
        {
            if (SentenceTerminators.Contains(text[i]))
            {
                // Include the terminator in the sentence.
                var sentence = text[start..(i + 1)].Trim();
                if (sentence.Length > 0)
                    sentences.Add(sentence);
                start = i + 1;
            }
        }

        // Capture any trailing text without a terminator.
        if (start < text.Length)
        {
            var remaining = text[start..].Trim();
            if (remaining.Length > 0)
                sentences.Add(remaining);
        }

        return sentences;
    }

    private static double ScoreSentence(string sentence, int position, int totalSentences)
    {
        double score = 0;

        // Prefer longer sentences (likely more informative), capped to avoid runaway scores.
        score += Math.Min(sentence.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length, 30);

        // Boost the first and last sentences as they often carry key information.
        if (position == 0)
            score += 10;
        else if (position == totalSentences - 1)
            score += 5;

        return score;
    }
}

using DocSummary.Models;
using DocSummary.Services;
using Microsoft.AspNetCore.Mvc;

namespace DocSummary.Controllers;

[ApiController]
[Route("api/[controller]")]
public class SummarizeController : ControllerBase
{
    private readonly IDocumentSummarizer _summarizer;

    public SummarizeController(IDocumentSummarizer summarizer)
    {
        _summarizer = summarizer;
    }

    [HttpPost]
    public ActionResult<SummarizeResponse> Summarize([FromBody] SummarizeRequest request)
    {
        var summary = _summarizer.Summarize(request.DocumentText, request.MaxSentences);

        return Ok(new SummarizeResponse
        {
            Summary = summary,
            OriginalLength = request.DocumentText.Length,
            SummaryLength = summary.Length
        });
    }
}

